def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find minimal edit to transform s_in to s_out."""
    # Find first position where they differ
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            # Try to determine what was replaced
            # Check if there's a simple character replacement
            if len(s_in) == len(s_out):
                return s_in[i], s_out[i], i
            else:
                # Different lengths - insertion/deletion
                # For simplicity, assume we're looking at the beginning
                return s_in[i], s_out[i], i

    # If we reach end, check length differences
    if len(s_in) != len(s_out):
        if len(s_in) > len(s_out):
            return s_in[len(s_out):], "", len(s_out)
        else:
            return "", s_out[len(s_in):], len(s_in)

    return "", "", -1

def propose_rule_candidates(s_in, s_out):
    """Generate rule candidates from a change."""
    # This is a simplified version - in practice this would be more sophisticated
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # Return the most specific candidate
    if old_sub and new_sub:
        return [(old_sub, new_sub)]
    elif old_sub and not new_sub:
        return [(old_sub, "")]
    else:
        return []

