inputs = ['uia', 'ck', 'cwv', 'hfa', 'jkheue']
outputs = ['ueja', 'ck', 'cwv', 'hfa', 'jkhahkfuahkf']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:", changed)

# Analyze each changed pair
rules = []

for idx, s_in, s_out in changed:
    print(f"\nAnalyzing pair {idx}: '{s_in}' -> '{s_out}'")
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)
    print(f"Minimal edit: '{old_sub}' -> '{new_sub}' at position {pos}")

    # Propose candidates
    candidates = propose_rule_candidates(s_in, s_out)
    print(f"Candidates: {candidates}")

    # Try the first candidate
    if candidates:
        rules.append(candidates[0])
        print(f"Added rule: {candidates[0]}")

print(f"\nProposed rules: {rules}")

# Test the rules
test_result = inputs[:]
for rule in rules:
    test_result = [s.replace(rule[0], rule[1]) for s in test_result]
print(f"Result with rules: {test_result}")
print(f"Expected:          {outputs}")

